// Doc describes one route for the OpenAPI document. Request and Response
// are zero values of the body types; nil means no body. Response is the
// "data" of the usual envelope unless Raw is set.
type Doc struct {
	Method   string
	Path     string // "{p}" stands for both /v1 and /v1/admin
	Summary  string
	Request  any
	Response any
	// Raw answers are plain JSON in the protocol's own shape, not the envelope.
	Raw bool
	// Form bodies are application/x-www-form-urlencoded.
	Form bool
}

